1	package indexroom
2	
3	import (
4		"errors"
5		"reflect"
6		"strings"
7		"sync"
8		"testing"
9	)
10	
11	// This file guards the QueryTxs FIRST page against a snapshot Restore that
12	// successfully replaces the whole main chain with a shorter one. The existing
13	// Restore/query overlap tests cover QueryTimeStats, and the existing
14	// QueryTxs overlap tests cover Reorg with an unfiltered query whose totals,
15	// matched-block count, and page length happen to coincide; neither can tell a
16	// page whose records are right but whose statistics were drawn from the other
17	// chain. These tests pin the first page, with a transaction filter, across
18	// every phase of a successful restore:
19	//
20	//   - while the snapshot is still being read (Restore holds no lock): the page
21	//     completes on the complete OLD chain, untouched by already-read fragments;
22	//   - once the page has resolved the old tip while the restore replacement is
23	//     waiting: records, TotalMatches, MatchedBlocks, and the pinned ToHeight
24	//     all come from the OLD chain;
25	//   - once the restore has installed the shorter chain: the same first-page
26	//     query comes wholly from the NEW chain — ToHeight follows the new tip, no
27	//     removed-height record survives, and old statistics are never stitched
28	//     onto new records.
29	//
30	// The scenario (To left at zero so the first page pins the observed tip; the
31	// filter is the id set {x,y}; page size 3, below both chains' match totals):
32	//
33	//	Old main chain, tip 6 (already ingested):
34	//	  h1 parent g  txs [x, q, x, w]    // x twice in one block: two occurrences
35	//	  h2 parent h1 txs [z]             // block with no matching tx
36	//	  h3 parent h2 txs [w, y, q]       // y among non-matching filler
37	//	  h4 parent h3 txs [r, r, x, y, y] // y twice; filler before the match
38	//	  h5 parent h4 txs [y, z]          // only-old height once the chain shrinks
39	//	  h6 parent h5 txs [p, q]          // trailing block with no matching tx
40	//	Version-1 snapshot replacing it, tip 4 (shorter; overlap content differs):
41	//	  j1 parent g  txs [x, y, z]
42	//	  j2 parent j1 txs [p, p]          // block with no matching tx
43	//	  j3 parent j2 txs [q, q, w]       // block with no matching tx
44	//	  j4 parent j3 txs [y, y, s, x]    // y twice in one block
45	//
46	// Old-chain answer (range 1..6): 7 matching occurrences over 4 matched
47	// blocks (h1, h3, h4, h5), pinned ToHeight 6. First page of 3:
48	//
49	//	{x h1 #0}, {x h1 #2}, {y h3 #1}
50	//
51	// New-chain answer (range 1..4): 5 matching occurrences over 2 matched
52	// blocks (j1, j4), pinned ToHeight 4. First page of 3:
53	//
54	//	{x j1 #0}, {y j1 #1}, {y j4 #0}
55	//
56	// The three counts are deliberately all different — page length 3, totals
57	// 7 vs 5, matched blocks 4 vs 2 — so "records are present and ordered" can
58	// never stand in for the statistics, and the statistics cover the WHOLE
59	// pinned range, not the records shown on this page. Every block hash
60	// differs between the chains, the overlap heights carry different
61	// transactions, and removed heights 5..6 hold an only-old match (y at h5):
62	// the two complete answers and any stitched mixture are distinguishable
63	// record by record.
64	
65	var (
66		restoreTxQuery    = TxQuery{TxIDs: []string{"x", "y"}, PageSize: restoreTxPageSize}
67		restoreTxPageSize = 3
68	)
69	
70	func restoreQueryOldChainBlocks() []Block {
71		return []Block{
72			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"x", "q", "x", "w"}},
73			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"z"}},
74			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"w", "y", "q"}},
75			{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"r", "r", "x", "y", "y"}},
76			{Height: 5, Hash: "h5", Parent: "h4", Txs: []string{"y", "z"}},
77			{Height: 6, Hash: "h6", Parent: "h5", Txs: []string{"p", "q"}},
78		}
79	}
