81	func restoreQueryNewChainBlocks() []Block {
82		return []Block{
83			{Height: 1, Hash: "j1", Parent: "g", Txs: []string{"x", "y", "z"}},
84			{Height: 2, Hash: "j2", Parent: "j1", Txs: []string{"p", "p"}},
85			{Height: 3, Hash: "j3", Parent: "j2", Txs: []string{"q", "q", "w"}},
86			{Height: 4, Hash: "j4", Parent: "j3", Txs: []string{"y", "y", "s", "x"}},
87		}
88	}
