90	// restoreTxNewSnapshot is the version-1 wire form of restoreQueryNewChainBlocks.
91	const restoreTxNewSnapshot = `{"version":1,"tip":4,"blocks":[` +
92		`{"height":1,"hash":"j1","parent":"g","txs":["x","y","z"]},` +
93		`{"height":2,"hash":"j2","parent":"j1","txs":["p","p"]},` +
94		`{"height":3,"hash":"j3","parent":"j2","txs":["q","q","w"]},` +
95		`{"height":4,"hash":"j4","parent":"j3","txs":["y","y","s","x"]}` +
96		`]}`
