98	func buildRestoreQueryOldChain(t *testing.T) *Index {
99		t.Helper()
100		index := New()
101		for _, b := range restoreQueryOldChainBlocks() {
102			if err := index.Append(b); err != nil {
103				t.Fatalf("setup append at %d: %v", b.Height, err)
104			}
105		}
106		return index
107	}
