109	// restoreFilteredHits is the filtered oracle: every matching occurrence in
110	// chain in height/position order, plus the number of blocks holding a match.
111	// It is derived from the supplied chain, not from the Index under test.
112	func restoreFilteredHits(chain []Block, ids []string) (hits []TxHit, blocks int64) {
113		filter := make(map[string]struct{}, len(ids))
114		for _, id := range ids {
115			filter[id] = struct{}{}
116		}
117		hits = []TxHit{}
118		for _, block := range chain {
119			matched := false
120			for position, tx := range block.Txs {
121				if _, ok := filter[tx]; !ok {
122					continue
123				}
124				hits = append(hits, TxHit{
125					Height:    block.Height,
126					BlockHash: block.Hash,
127					TxID:      tx,
128					Position:  position,
129				})
130				matched = true
131			}
132			if matched {
133				blocks++
134			}
135		}
136		return hits, blocks
137	}
138	
139	// restoreReferenceTxPage is one first/continuing page of the complete
140	// filtered answer for chain (heights 1..len(chain)) sliced at offset, with
141	// the whole-range statistics the page must carry. The cursor is excluded;
142	// callers exercise it by actually following it.
143	func restoreReferenceTxPage(chain []Block, pageSize int, offset int64) TxPage {
144		full, blocks := restoreFilteredHits(chain, restoreTxQuery.TxIDs)
145		rest := full[offset:]
146		end := pageSize
147		if end > len(rest) {
148			end = len(rest)
149		}
150		return TxPage{
151			Hits:          append([]TxHit{}, rest[:end]...),
152			TotalMatches:  int64(len(full)),
153			MatchedBlocks: blocks,
154			ToHeight:      int64(len(chain)),
155		}
156	}
