162			Hits: []TxHit{
163				{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
164				{Height: 1, BlockHash: "h1", TxID: "x", Position: 2},
165				{Height: 3, BlockHash: "h3", TxID: "y", Position: 1},
166			},
167			TotalMatches:  7,
168			MatchedBlocks: 4,
169			ToHeight:      6,
170		}
171	}
