173	func literalRestoreTxNewFirstPage() TxPage {
174		return TxPage{
175			Hits: []TxHit{
176				{Height: 1, BlockHash: "j1", TxID: "x", Position: 0},
177				{Height: 1, BlockHash: "j1", TxID: "y", Position: 1},
178				{Height: 4, BlockHash: "j4", TxID: "y", Position: 0},
179			},
180			TotalMatches:  5,
181			MatchedBlocks: 2,
182			ToHeight:      4,
183		}
