406	// restoreQueryHooks are deterministic rendezvous for the QueryTxs/Restore
407	// overlap tests: a parked first page holds the lock with the tip-bound
408	// height already resolved; a parked restore has the new chain fully
409	// installed but has not returned and still holds the lock.
410	type restoreQueryHooks struct {
411		firstParked  chan struct{}
412		releaseFirst chan struct{}
413	
414		restoreParked  chan struct{}
415		releaseRestore chan struct{}
416	
417		allowedRestoreTip int64
418		firstOnce         sync.Once
419		restoreOnce       sync.Once
420	}
421	
422	func installRestoreQueryHooks(t *testing.T, parkFirst bool, restoreTip int64) *restoreQueryHooks {
423		t.Helper()
424		h := &restoreQueryHooks{
425			allowedRestoreTip: restoreTip,
426			restoreParked:     make(chan struct{}),
427			releaseRestore:    make(chan struct{}),
428		}
429		if parkFirst {
430			h.firstParked = make(chan struct{})
431			h.releaseFirst = make(chan struct{})
432		}
433		queryTxsHookLocked = func(from, to int64, continuation bool) {
434			if continuation || h.firstParked == nil {
435				return // only first pages participate in the rendezvous
436			}
437			if from != 1 {
438				t.Errorf("query hook resolved from=%d, want 1", from)
439			}
440			h.firstOnce.Do(func() { close(h.firstParked) })
441			<-h.releaseFirst
442		}
443		restoreAppliedHookLocked = func(newTip int64) {
444			if newTip != h.allowedRestoreTip {
445				t.Errorf("restore hook saw newTip=%d, want %d", newTip, h.allowedRestoreTip)
446			}
447			h.restoreOnce.Do(func() { close(h.restoreParked) })
448			<-h.releaseRestore
449		}
450		t.Cleanup(func() {
451			queryTxsHookLocked = nil
452			restoreAppliedHookLocked = nil
453		})
454		return h
455	}
456	
457	// A first page that has resolved the OLD tip (6) and still holds the lock
458	// when the restore replacement becomes ready must finish on the complete
459	// old chain: records, whole-range totals, matched-block count, and pinned
460	// ToHeight all describe the old chain. The restore applies only afterwards;
461	// the same query then answers from the new chain.
462	func TestQueryTxsInFlightObservesCompleteOldChainBeforeRestore(t *testing.T) {
463		index := buildRestoreQueryOldChain(t)
464		h := installRestoreQueryHooks(t, true, 4)
465		oldChain, newChain := restoreQueryOldChainBlocks(), restoreQueryNewChainBlocks()
466	
467		result := make(chan TxPage, 1)
468		errCh := make(chan error, 1)
469		go func() {
470			page, err := index.QueryTxs(restoreTxQuery)
471			if err != nil {
472				errCh <- err
473				return
474			}
475			result <- page
476		}()
477	
478		<-h.firstParked // query holds index.mu and has pinned the old tip 6
479		restoreDone := make(chan error, 1)
480		go func() {
481			// A fully readable snapshot parses end-to-end and then blocks on
482			// index.mu behind the parked first page.
483			restoreDone <- index.Restore(strings.NewReader(restoreTxNewSnapshot))
484		}()
485	
486		close(h.releaseFirst) // the query scans and finishes on the old chain first
487		var got TxPage
488		select {
489		case got = <-result:
490		case err := <-errCh:
491			t.Fatalf("concurrent query failed: %v", err)
492		}
493		want := restoreReferenceTxPage(oldChain, restoreTxPageSize, 0)
494		if err := classifyTxPage(got, want, restoreReferenceTxPage(newChain, restoreTxPageSize, 0),
495			mustRestoreFilteredHits(t, oldChain), mustRestoreFilteredHits(t, newChain)); err != nil {
496			t.Fatalf("in-flight first page did not return one complete chain:\n%v", err)
497		}
498		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
499			t.Fatalf("query holding the lock across restore commit must see the old chain:\n%+v", got)
500		}
501		if !reflect.DeepEqual(got.Hits, literalRestoreTxOldFirstPage().Hits) {
502			t.Fatalf("old first page hits=%v, want literal old records", got.Hits)
503		}
504		if got.NextCursor == "" {
505			t.Fatal("old first page over 7 matches must carry a cursor")
506		}
507	
508		close(h.releaseRestore) // the parked restore can now commit and return
509		if err := <-restoreDone; err != nil {
510			t.Fatalf("restore failed: %v", err)
511		}
512		if index.Tip != 4 {
513			t.Fatalf("tip after restore=%d, want 4", index.Tip)
514		}
515	
516		after, err := index.QueryTxs(restoreTxQuery)
517		if err != nil {
518			t.Fatal(err)
519		}
520		if !reflect.DeepEqual(viewOf(after), viewOf(literalRestoreTxNewFirstPage())) {
521			t.Fatalf("query after restore must see the complete new chain:\n%+v", after)
522		}
523	}
