525	// A first page issued while a successful restore has already installed the
526	// shorter chain but has not yet returned must wait and then observe the
527	// complete NEW chain: ToHeight follows the new tip (4), every record (with
528	// its block hash and position) is a new-chain record, and totals count the
529	// new range only — never old statistics stitched onto new records.
530	func TestQueryTxsIssuedAtRestoreCommitSeesNewChain(t *testing.T) {
531		index := buildRestoreQueryOldChain(t)
532		h := installRestoreQueryHooks(t, false, 4)
533		oldChain, newChain := restoreQueryOldChainBlocks(), restoreQueryNewChainBlocks()
534	
535		restoreDone := make(chan error, 1)
536		go func() {
537			restoreDone <- index.Restore(strings.NewReader(restoreTxNewSnapshot))
538		}()
539		<-h.restoreParked // new chain installed (tip 4), Restore still holds the lock
540	
541		result := make(chan TxPage, 1)
542		go func() {
543			page, err := index.QueryTxs(restoreTxQuery)
544			if err != nil {
545				t.Errorf("query during restore commit failed: %v", err)
546				return
547			}
548			result <- page
549		}()
550		select {
551		case got := <-result:
552			t.Fatalf("query returned while the restore still held the lock: %+v", got)
553		default:
554		}
555	
556		close(h.releaseRestore)
557		if err := <-restoreDone; err != nil {
558			t.Fatalf("restore failed: %v", err)
559		}
560	
561		got := <-result
562		want := restoreReferenceTxPage(newChain, restoreTxPageSize, 0)
563		if err := classifyTxPage(got, restoreReferenceTxPage(oldChain, restoreTxPageSize, 0), want,
564			mustRestoreFilteredHits(t, oldChain), mustRestoreFilteredHits(t, newChain)); err != nil {
565			t.Fatalf("query across restore commit did not return one complete chain:\n%v", err)
566		}
567		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
568			t.Fatalf("query after restore commit must see the complete new chain:\n%+v", got)
569		}
570		if !reflect.DeepEqual(got.Hits, literalRestoreTxNewFirstPage().Hits) {
571			t.Fatalf("new first page hits=%v, want literal new records", got.Hits)
572		}
573		if got.ToHeight != 4 || got.TotalMatches != 5 || got.MatchedBlocks != 2 {
574			t.Fatalf("new page must carry new-chain statistics and tip: %+v", got)
575		}
576		for _, hit := range got.Hits {
577			if hit.Height > 4 || strings.HasPrefix(hit.BlockHash, "h") {
578				t.Fatalf("removed-height record leaked into the restore-commit page: %+v", hit)
579			}
580		}
581	
582		// The cursor mints against the new chain and paginates exactly its
583		// filtered occurrences, statistics pinned to the first page throughout.
584		query := restoreTxQuery
585		query.Cursor = got.NextCursor
586		all := append([]TxHit{}, got.Hits...)
587		for pageNo := 1; ; pageNo++ {
588			page, err := index.QueryTxs(query)
589			if err != nil {
590				t.Fatalf("new-chain pagination broke at page %d: %v", pageNo, err)
591			}
592			if page.TotalMatches != 5 || page.MatchedBlocks != 2 || page.ToHeight != 4 {
593				t.Fatalf("page %d statistics drifted from the pinned first page: %+v", pageNo, page)
594			}
595			all = append(all, page.Hits...)
596			if page.NextCursor == "" {
597				break
598			}
599			query.Cursor = page.NextCursor
600		}
601		if wantAll, _ := restoreFilteredHits(newChain, restoreTxQuery.TxIDs); !reflect.DeepEqual(all, wantAll) {
602			t.Fatalf("new-chain pagination=%v, want %v", all, wantAll)
603		}
604	}
605	
606	func mustRestoreFilteredHits(t *testing.T, chain []Block) []TxHit {
607		t.Helper()
608		hits, _ := restoreFilteredHits(chain, restoreTxQuery.TxIDs)
609		return hits
610	}
611	
612	// The complete-chain classifier must reject exactly the mixtures this
613	// regression targets: right-looking records under the other chain's tip or
614	// statistics — including a correctly ordered page stitched from both chains
615	// — while accepting both pure answers.
616	func TestClassifyRestoreTxPageRejectsMixtures(t *testing.T) {
617		oldRef := literalRestoreTxOldFirstPage()
618		newRef := literalRestoreTxNewFirstPage()
619		oldAll := mustRestoreFilteredHits(t, restoreQueryOldChainBlocks())
620		newAll := mustRestoreFilteredHits(t, restoreQueryNewChainBlocks())
621		classify := func(page TxPage) error { return classifyTxPage(page, oldRef, newRef, oldAll, newAll) }
622	
623		if err := classify(oldRef); err != nil {
624			t.Fatalf("pure old page rejected: %v", err)
625		}
626		if err := classify(newRef); err != nil {
627			t.Fatalf("pure new page rejected: %v", err)
628		}
629	
630		// New-chain records and statistics under the stale OLD tip height: looks
631		// internally counted, but claims removed heights 5..6 are in range.
632		mixed := newRef
633		mixed.ToHeight = oldRef.ToHeight
634		if err := classify(mixed); err == nil {
635			t.Fatal("new-chain page under the old tip height was accepted")
636		} else if !strings.Contains(err.Error(), "MIXED") {
637			t.Fatalf("new-records/old-tip mixture not reported as MIXED:\n%v", err)
638		}
639	
640		// Old-chain records and tip with the NEW chain's whole-range statistics:
641		// the records are right for the old chain but totals/blocks came from the
642		// shorter one — the exact "records correct, statistics from the wrong
643		// chain" defect the fixture exists to expose.
644		mixed = oldRef
645		mixed.TotalMatches = newRef.TotalMatches
646		mixed.MatchedBlocks = newRef.MatchedBlocks
647		if err := classify(mixed); err == nil {
648			t.Fatal("old records with new-chain statistics were accepted")
649		} else if !strings.Contains(err.Error(), "MIXED") {
650			t.Fatalf("old-records/new-stats mixture not reported as MIXED:\n%v", err)
651		}
652	
653		// New-chain records and tip with the OLD chain's whole-range statistics.
654		mixed = newRef
655		mixed.TotalMatches = oldRef.TotalMatches
656		mixed.MatchedBlocks = oldRef.MatchedBlocks
657		if err := classify(mixed); err == nil {
658			t.Fatal("new records with old-chain statistics were accepted")
659		} else if !strings.Contains(err.Error(), "MIXED") {
660			t.Fatalf("new-records/old-stats mixture not reported as MIXED:\n%v", err)
661		}
662	
663		// Old-chain page that nevertheless claims the shortened NEW tip: it
664		// counts removed height 5 while promising ToHeight 4.
665		mixed = oldRef
666		mixed.ToHeight = newRef.ToHeight
667		if err := classify(mixed); err == nil {
668			t.Fatal("old records under the new tip height were accepted")
669		} else if !strings.Contains(err.Error(), "MIXED") {
670			t.Fatalf("old-records/new-tip mixture not reported as MIXED:\n%v", err)
671		}
672	
673		// An ordered-looking page that stitches records from both chains:
674		// x@h1 exists only on the old chain (restore replaces height 1 too, so
675		// even the height-1 hashes differ), y@h3 is old-only, and y@j4 is
676		// new-only. Height and position ordering is intact, so ordering-only
677		// checks accept it.
678		mixed = oldRef
679		mixed.Hits = []TxHit{
680			{Height: 1, BlockHash: "h1", TxID: "x", Position: 0}, // old only
681			{Height: 3, BlockHash: "h3", TxID: "y", Position: 1}, // old only
682			{Height: 4, BlockHash: "j4", TxID: "y", Position: 0}, // new only
683		}
684		if err := classify(mixed); err == nil {
685			t.Fatal("stitched hits from both chains were accepted")
686		} else if !strings.Contains(err.Error(), "MIXED") {
687			t.Fatalf("stitched-records mixture not reported as MIXED:\n%v", err)
688		}
689	
690		// Plain corruption: statistics belonging to neither chain.
691		corrupt := newRef
692		corrupt.MatchedBlocks = 99
693		if err := classify(corrupt); err == nil {
694			t.Fatal("corrupt statistics matching neither chain were accepted")
695		} else if !strings.Contains(err.Error(), "CORRUPT") {
696			t.Fatalf("corrupt page not reported as CORRUPT:\n%v", err)
697		}
698	}
699	
700	// Sustained overlap, no hooks: restores alternate between the old-chain
701	// snapshot and the shorter new-chain snapshot while readers issue first
702	// pages continuously. Every page must classify as one complete chain, with
703	// branch identity confirmed record by record; success never depends on
704	// which side of a restore a query happened to land. This supplements the
705	// deterministic rendezvous tests above rather than replacing them.
706	func TestQueryTxsRepeatedRestoresStayConsistent(t *testing.T) {
707		index := buildRestoreQueryOldChain(t)
708		oldChain := restoreQueryOldChainBlocks()
709		newChain := restoreQueryNewChainBlocks()
710		oldSnapshot := exportString(t, index) // version 1: none of the blocks carry times
711		if !strings.Contains(oldSnapshot, `"version":1`) {
712			t.Fatalf("test setup: old snapshot must be version 1: %s", oldSnapshot)
713		}
714		oldRef := restoreReferenceTxPage(oldChain, restoreTxPageSize, 0)
715		newRef := restoreReferenceTxPage(newChain, restoreTxPageSize, 0)
716		oldAll := mustRestoreFilteredHits(t, oldChain)
717		newAll := mustRestoreFilteredHits(t, newChain)
718	
719		const restorers = 2
720		const rounds = 40
721		const readers = 4
722		const reads = 80
723	
724		stop := make(chan struct{})
725		var wg sync.WaitGroup
726		for r := 0; r < restorers; r++ {
727			wg.Add(1)
728			go func(seed int) {
729				defer wg.Done()
730				for i := 0; i < rounds; i++ {
731					select {
732					case <-stop:
733						return
734					default:
735					}
736					snapshot := restoreTxNewSnapshot
737					if (i+seed)%2 == 0 {
738						snapshot = oldSnapshot
739					}
740					if err := index.Restore(strings.NewReader(snapshot)); err != nil {
741						t.Errorf("restore failed: %v", err)
742						return
743					}
744				}
745			}(r)
746		}
747		for r := 0; r < readers; r++ {
748			wg.Add(1)
749			go func() {
750				defer wg.Done()
751				for i := 0; i < reads; i++ {
752					select {
753					case <-stop:
754						return
755					default:
756					}
757					page, err := index.QueryTxs(restoreTxQuery)
758					if err != nil {
759						t.Errorf("first page failed: %v", err)
760						return
761					}
762					var branchHits []TxHit
763					switch page.ToHeight {
764					case 6:
765						branchHits = oldAll
766					case 4:
767						branchHits = newAll
768					default:
769						t.Errorf("first page pinned unknown tip %d", page.ToHeight)
770						return
771					}
772					if err := classifyTxPage(page, oldRef, newRef, oldAll, newAll); err != nil {
773						t.Errorf("%v", err)
774						return
775					}
776					if !reflect.DeepEqual(page.Hits, branchHits[:len(page.Hits)]) {
777						t.Errorf("first page records do not match the pinned branch:\n%+v", page.Hits)
778						return
779					}
780				}
781			}()
782		}
783		wg.Wait()
784		close(stop)
785	
786		// Leave the index deterministically on the shorter new chain and verify
787		// the complete filtered answer, cursor pagination included.
788		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
789			t.Fatalf("final restore failed: %v", err)
790		}
791		first, err := index.QueryTxs(restoreTxQuery)
792		if err != nil {
793			t.Fatal(err)
794		}
795		if err := classifyTxPage(first, oldRef, newRef, oldAll, newAll); err != nil {
796			t.Fatalf("final first page is not one complete chain:\n%v", err)
797		}
798		if !reflect.DeepEqual(viewOf(first), viewOf(newRef)) {
799			t.Fatalf("final first page is not the complete new-chain answer:\n%+v", first)
800		}
801		query := restoreTxQuery
802		query.Cursor = first.NextCursor
803		all := append([]TxHit{}, first.Hits...)
804		for query.Cursor != "" {
805			page, err := index.QueryTxs(query)
806			if err != nil {
807				t.Fatalf("final pagination failed: %v", err)
808			}
809			if page.TotalMatches != 5 || page.MatchedBlocks != 2 || page.ToHeight != 4 {
810				t.Fatalf("final pagination statistics drifted: %+v", page)
811			}
812			all = append(all, page.Hits...)
813			query.Cursor = page.NextCursor
814		}
815		if !reflect.DeepEqual(all, newAll) {
816			t.Fatalf("final chain pagination=%v, want %v", all, newAll)
817		}
818	}
819	
820	// A first page pinned to the OLD chain before the restore keeps its semantics
821	// under guard: here the snapshot replaces the whole chain, so the pinned
822	// range [1,6] is no longer covered and the old cursor must fail with
823	// ErrQueryChanged and a zeroed page rather than resume on mixed data.
824	func TestQueryTxsCursorAfterWholeChainRestoreIsChangedAndZeroed(t *testing.T) {
825		index := buildRestoreQueryOldChain(t)
826		first, err := index.QueryTxs(restoreTxQuery)
827		if err != nil {
828			t.Fatal(err)
829		}
830		if first.ToHeight != 6 || first.TotalMatches != 7 || first.NextCursor == "" {
831			t.Fatalf("unexpected first page: %+v", first)
832		}
833	
834		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
835			t.Fatalf("restore refused: %v", err)
836		}
837		page, err := index.QueryTxs(TxQuery{
838			TxIDs:    restoreTxQuery.TxIDs,
839			PageSize: restoreTxPageSize,
840			Cursor:   first.NextCursor,
841		})
842		if !errors.Is(err, ErrQueryChanged) {
843			t.Fatalf("old cursor across restore: err=%v page=%+v, want ErrQueryChanged", err, page)
844		}
845		if !reflect.DeepEqual(page, TxPage{}) {
846			t.Fatalf("changed continuation must return a zeroed page, got %+v", page)
847		}
848	}
