	for _, id := range []string{"snap-1", "snap-2a", "snap-2b"} {
		p, qerr := index.QueryTxs(TxQuery{TxIDs: []string{id}})
		if qerr != nil || p.TotalMatches != 0 {
			t.Fatalf("snapshot tx %q queryable early: page=%+v err=%v", id, p, qerr)
		}
	}
