	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(mid.Hits, []TxHit{{Height: 3, BlockHash: "h3", TxID: "mid-3", Position: 0}}) {
		t.Fatalf("mid-3 hits=%v, want the single appended occurrence", mid.Hits)
	}
	if mid.ToHeight != 3 {
		t.Fatalf("mid-3 query ToHeight=%d, want 3", mid.ToHeight)
	}

